  <div class="modal" id="save-as-modal" tabindex="-1" role="dialog">
    <div class="modal-dialog" role="document">
      <div class="modal-content">
        <div class="modal-body">
          <div class="container-fluid">
            <div class="row">
              <div class="col text-danger" id="save-as-err-msg"></div>
            </div>
            <div class="row">
              <div class="col">
                <div class="input-group">
                  <input
                    type="text"
                    class="form-control"
                    id="base-name-save-as-input"
                    placeholder="file name"
                  />
                  <div class="input-group-append">
                    <select class="form-control" id="file-ext-save-as-select">
                      <option value="xlsx" selected>.xlsx</option>
                      <option value="xls">.xls</option>
                      <option value="tsv">.tsv</option>
                      <option value="csv">.csv</option>
                      <option value="json">.json</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>
            <div
              class="form-row align-items-center d-none"
              id="save-as-json-options"
            >
              <div class="col-auto">
                <div class="form-check mt-2 mr-2">
                  <input
                    class="form-check-input"
                    type="checkbox"
                    id="save-as-json-use-index"
                  />
                  <label class="form-check-label" for="save-as-json-use-index">
                    Save as object with index key
                  </label>
                </div>
              </div>
              <div class="col-4">
                <label class="sr-only" for="save-as-json-index-key">Name</label>
                <input
                  type="text"
                  class="form-control mt-2"
                  id="save-as-json-index-key"
                  disabled
                />
              </div>
            </div>
            <div class="row mt-3">
              <div class="col-2 col-sm-6"></div>
              <div class="col d-flex justify-content-end">
                <button
                  type="button"
                  class="btn btn-secondary"
                  data-dismiss="modal"
                >
                  Cancel
                </button>
              </div>
              <div class="col d-flex justify-content-end">
                <button
                  type="button"
                  class="btn btn-primary"
                  id="save-as-confirm-btn"
                >
                  Save
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

